    private static void pursuit(ServerLevel level,ServerPlayer player,boolean panzer)throws Exception{
        for(int x=1196;x<=1220;x++)for(int z=1;z<=4;z++){
            level.setBlock(new BlockPos(x,78,z),Blocks.STONE.defaultBlockState(),3);
            level.setBlock(new BlockPos(x,79,z),ZombieroolModBlocks.PATH.get().defaultBlockState(),3);
            for(int y=80;y<=84;y++)level.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);
            if(x>=1205&&x<=1213)level.setBlock(new BlockPos(x,81,z),Blocks.STONE.defaultBlockState(),3);
        }
        player.setPos(1218.5,79,2.5);player.setHealth(player.getMaxHealth());player.clearFire();
        var boss=(panzer?ZombieroolModEntities.PANZER:ZombieroolModEntities.BRUTUS).get().create(level);
        boss.moveTo(1200.5,79,2.5,0,0);boss.setOnGround(true);
        boss.getPersistentData().putBoolean("zr_special_spawner",true);
        if(panzer)boss.beginDescent();else boss.playBossAnimation("spawn",50);
        check(level.addFreshEntity(boss)&&boss.isAlive(),"Pursuit fixture uses an authorized live spawner boss");boolean ducked=false;long time=level.getGameTime();var serverTicks=net.minecraft.server.MinecraftServer.class.getDeclaredField("tickCount");serverTicks.setAccessible(true);int serverTime=serverTicks.getInt(level.getServer());
        for(int t=0;t<280&&boss.getX()<1216;t++){
            level.getServer().getWorldData().overworldData().setGameTime(time+t+1);
            serverTicks.setInt(level.getServer(),serverTime+t);if(t%40==20&&!boss.isDescending()){boss.invulnerableTime=0;boss.hurt(level.damageSources().generic(),1);}float previousYaw=boss.yBodyRot;boolean descending=boss.isDescending();boss.tickCount++;boss.tick();ducked|=boss.isBossCrouched();
        }
        check(!boss.isNoAi()&&boss.getX()>1214.5,(panzer?"Panzer":"Brutus")+" resumes pursuit after arrival and crosses a two-block passage");
        serverTicks.setInt(level.getServer(),serverTime);
        check(ducked&&!boss.isBossCrouched()&&boss.getBbHeight()>2.6,"Boss ducks under ceilings and regains its full height outside");
        var hurt=SpecialEnemyEntity.class.getDeclaredMethod("getHurtSound",net.minecraft.world.damagesource.DamageSource.class);hurt.setAccessible(true);
        check(hurt.invoke(boss,level.damageSources().generic())==null,"Boss damage has no vanilla hurt sound");
        boss.releaseCapture();boss.discard();
    }
